#!/usr/bin/env python3
"""
Round nh2 (culprits-tiles-more), 16 October 2026, from the Invasion of
non-humans chat. Needs nonhuman2_tiles.py (applied). Writes only nonhuman_*.py
scripts and scripts/lib/nhcommon.py, scripts/lib/nhwdpa.py; they write only
under nonhuman/.

Changed:
  nonhuman_paddd.py       no dot is made for events given only as outlines
  nonhuman_extraction.py  measures with the shared lib/nhwdpa.py
New:
  lib/nhwdpa.py                  the WDPA download, reading and distance measuring, shared
  nonhuman_oilgas.py             OGIM oil and gas sites by distance from protected areas (long; carries on run to run)
  nonhuman_pestplants.py         EU plants making plant protection products and biocides (E-PRTR)
  nonhuman_bannedexports.py      EU banned pesticide export notifications, 2024 (Unearthed and Public Eye)
  nonhuman_panbans.py            PAN International's consolidated list of banned pesticides
  nonhuman_papressure.py         human modification inside each protected area (gHM, WDPA)
  nonhuman_roads.py              GRIP4 road density
  nonhuman_wetlands.py           wetlands drained since 1700 (Fluet-Chouinard et al. 2023)
  nonhuman_trawl_mpas.py         trawling and dredging inside marine protected areas (needs GFW_TOKEN)
  nonhuman_wgi.py                Worldwide Governance Indicators

Afterwards, Actions > refresh > Run workflow with
  nonhuman_pestplants nonhuman_bannedexports nonhuman_panbans nonhuman_roads nonhuman_wetlands nonhuman_wgi nonhuman_trawl_mpas nonhuman_paddd
then, one at a time: nonhuman_papressure, then nonhuman_oilgas (run it again until oilgas.build.json says complete).
Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/lib/nhcommon.py': '', 'scripts/lib/nhwdpa.py': '', 'scripts/nonhuman_anthromes.py': '', 'scripts/nonhuman_bannedexports.py': '', 'scripts/nonhuman_extraction.py': '', 'scripts/nonhuman_faostat.py': '', 'scripts/nonhuman_firsts.py': '', 'scripts/nonhuman_griis.py': '', 'scripts/nonhuman_invacost.py': '', 'scripts/nonhuman_oilgas.py': '', 'scripts/nonhuman_paddd.py': '', 'scripts/nonhuman_panbans.py': '', 'scripts/nonhuman_papressure.py': '', 'scripts/nonhuman_pestco.py': '', 'scripts/nonhuman_pestgrids.py': '', 'scripts/nonhuman_pestplants.py': '', 'scripts/nonhuman_pestrisk.py': '', 'scripts/nonhuman_roads.py': '', 'scripts/nonhuman_trawl_mpas.py': '', 'scripts/nonhuman_wetlands.py': '', 'scripts/nonhuman_wgi.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("nonhuman2_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"nonhuman2_tiles: wrote {path}")
    if not changed:
        print("nonhuman2_tiles: already applied")


if __name__ == "__main__":
    main()
